import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // Resolve each role and its parent chain; the visited set guards against cycles.
  const grants = new Set<string>();
  const visited = new Set<string>();
  for (const start of user.roles) {
    for (let name: string | undefined = start; name !== undefined && !visited.has(name); name = directory[name]?.parent) {
      visited.add(name);
      for (const grant of directory[name]?.grants ?? []) grants.add(grant);
    }
  }
  return grants;
}
EOF
cat > src/reports.ts <<'EOF'
import type { Directory, Download, Report, User } from "./types.ts";
import { allows } from "./policy.ts";

export function downloadReport(user: User, id: string, directory: Directory, reports: Report[]): Download {
  if (!allows(user, "report:download", directory)) return { status: 403, body: "Forbidden" };
  const report = reports.find(report => report.id === id);
  if (!report) return { status: 404, body: "Not found" };
  return { status: 200, body: report.body };
}
EOF
